package com.thangit.boardinghouse.service;

import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import static com.thangit.boardinghouse.service.CommunicationService.number;

/** Short claim/finish transactions. SMTP/HTTPS executes only after the lease is committed.
 * An expired lease becomes UNKNOWN, never an automatic resend of a possibly accepted request.
 */
@Service
public class ExternalCommunicationWorker {
    private ContractDeliveryService contractDelivery;
    @org.springframework.beans.factory.annotation.Autowired public void contractDelivery(ContractDeliveryService delivery){this.contractDelivery=delivery;}
    final JdbcClient db;final CommunicationJobs jobs;final CommunicationSender sender;final TransactionTemplate tx;
    public ExternalCommunicationWorker(JdbcClient db,CommunicationJobs jobs,CommunicationSender sender,org.springframework.transaction.PlatformTransactionManager manager){this.db=db;this.jobs=jobs;this.sender=sender;tx=new TransactionTemplate(manager);}
    static LocalDateTime realNow(){return LocalDateTime.ofInstant(Instant.now(),ZoneOffset.UTC);}
    public int runBatch(LocalDateTime businessNow){if(!sender.independentWorker())return 0;
        tx.executeWithoutResult(status->db.sql("UPDATE communication_deliveries SET status='UNKNOWN',result_code='DISPATCH_LEASE_EXPIRED',retryable=FALSE,finished_at=:at,lease_token=NULL,lease_until=NULL WHERE status='DISPATCHING' AND lease_until<:real").param("at",businessNow).param("real",realNow()).update());
        int done=0;for(int i=0;i<10;i++){Map<String,Object> delivery;try{delivery=tx.execute(status->claim(businessNow));}catch(org.springframework.dao.TransientDataAccessException conflict){break;}if(delivery==null)break;if(delivery.containsKey("skipped"))continue;
            long id=number(delivery,"id");String lease=delivery.get("lease_token").toString();CommunicationSender.Result result;
            try{result=contractDelivery!=null&&delivery.get("channel").equals("EMAIL")&&Objects.toString(delivery.get("source_key"),"").startsWith("ONBOARD:")?contractDelivery.send(delivery):sender.send(number(delivery,"property_id"),delivery.get("channel").toString(),delivery.get("business_key").toString(),number(delivery,"recipient_id"),delivery.get("title").toString(),delivery.get("body").toString());}
            catch(com.thangit.boardinghouse.common.exception.AuthException invalid){result=new CommunicationSender.Result("FAILED",invalid.code(),null,false);}
            catch(Exception uncertain){result=new CommunicationSender.Result("UNKNOWN","PROVIDER_OUTCOME_UNCONFIRMED",null,false);}
            final CommunicationSender.Result outcome=result;tx.executeWithoutResult(status->finish(delivery,lease,outcome,businessNow));done++;
        }return done;
    }
    Map<String,Object> claim(LocalDateTime at){var rows=db.sql("SELECT * FROM communication_deliveries WHERE channel<>'IN_APP' AND status IN ('SCHEDULED','QUEUED','FAILED') AND next_attempt_at<=:at AND attempt_count<3 AND (status<>'FAILED' OR retryable=TRUE) ORDER BY next_attempt_at,id LIMIT 1 FOR UPDATE SKIP LOCKED").param("at",at).query().listOfRows();if(rows.isEmpty())return null;var delivery=rows.getFirst();long id=number(delivery,"id"),recipient=number(delivery,"recipient_id");boolean valid;try{valid=jobs.current(delivery,at);}catch(com.thangit.boardinghouse.common.exception.AuthException revoked){valid=false;}if(!valid){jobs.finish(id,"CANCELLED","SOURCE_OR_SCOPE_CHANGED",at);return deliveryCancelled();}if(jobs.quiet(recipient,at,delivery.get("category").toString())){db.sql("UPDATE communication_deliveries SET next_attempt_at=:next WHERE id=:id").param("next",at.plusHours(1)).param("id",id).update();return deliveryCancelled();}int limit=delivery.get("rule_id")==null?5:db.sql("SELECT daily_limit FROM communication_rules WHERE id=:id").param("id",delivery.get("rule_id")).query(Integer.class).single();long sent=db.sql("SELECT COUNT(*) FROM communication_deliveries WHERE recipient_id=:recipient AND property_id=:property AND channel=:channel AND finished_at>=:day AND finished_at<:end AND status IN ('SENT','DELIVERED')").param("recipient",recipient).param("property",delivery.get("property_id")).param("channel",delivery.get("channel")).param("day",at.toLocalDate().atStartOfDay()).param("end",at.toLocalDate().plusDays(1).atStartOfDay()).query(Long.class).single();if(sent>=limit){db.sql("UPDATE communication_deliveries SET next_attempt_at=:next WHERE id=:id").param("next",at.toLocalDate().plusDays(1).atTime(9,0)).param("id",id).update();return deliveryCancelled();}String lease=UUID.randomUUID().toString();db.sql("UPDATE communication_deliveries SET status='DISPATCHING',attempt_count=attempt_count+1,lease_token=:lease,lease_until=:until,retryable=FALSE WHERE id=:id").param("lease",lease).param("until",realNow().plusMinutes(3)).param("id",id).update();delivery.put("lease_token",lease);delivery.put("attempt_count",number(delivery,"attempt_count")+1);return delivery;}
    Map<String,Object> deliveryCancelled(){return Map.of("skipped",true);}
    void finish(Map<String,Object> delivery,String lease,CommunicationSender.Result outcome,LocalDateTime at){long id=number(delivery,"id");var rows=db.sql("SELECT status,lease_token FROM communication_deliveries WHERE id=:id FOR UPDATE").param("id",id).query().listOfRows();if(rows.isEmpty()||!"DISPATCHING".equals(rows.getFirst().get("status"))||!lease.equals(rows.getFirst().get("lease_token")))return;String state=Set.of("SENT","DELIVERED","FAILED","UNKNOWN","SIMULATED").contains(outcome.outcome())?outcome.outcome():"UNKNOWN";String code=outcome.code()!=null&&outcome.code().matches("[A-Z0-9_]{1,80}")?outcome.code():"PROVIDER_ERROR";String reference=outcome.providerReference()!=null&&outcome.providerReference().matches("[a-zA-Z0-9_:-]{1,180}")?outcome.providerReference():null;int attempt=((Number)delivery.get("attempt_count")).intValue();boolean retry=state.equals("FAILED")&&outcome.retryable()&&attempt<3;db.sql("INSERT INTO communication_attempts(delivery_id,attempt_number,outcome,result_code,provider_reference,attempted_at) VALUES(:id,:attempt,:outcome,:code,:reference,:at)").param("id",id).param("attempt",attempt).param("outcome",state).param("code",code).param("reference",reference).param("at",at).update();db.sql("UPDATE communication_deliveries SET status=:state,result_code=:code,provider_reference=:reference,finished_at=:at,retryable=:retry,next_attempt_at=:next,lease_token=NULL,lease_until=NULL WHERE id=:id").param("state",state).param("code",code).param("reference",reference).param("at",at).param("retry",retry).param("next",at.plusMinutes(attempt==1?1:5)).param("id",id).update();}
}
